<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>AI 模型市场 - Apimart Static</title>
  <style>
    :root {
      --text: #111214;
      --muted: #7b7f86;
      --soft: #f5f6f7;
      --line: #e7e8ea;
      --panel: #ffffff;
      --green: #0aa66a;
      --shadow: 0 16px 42px rgba(20, 24, 32, .08);
      --radius: 8px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
      color: var(--text);
      background: #fff;
    }

    * { box-sizing: border-box; }
    body { margin: 0; min-width: 320px; }
    button, input, select { font: inherit; }
    .container { width: min(1700px, calc(100% - 72px)); margin: 0 auto; }

    .site-header {
      height: 92px;
      border-bottom: 1px solid var(--line);
      background: rgba(255, 255, 255, .94);
      display: flex;
      align-items: center;
      position: sticky;
      top: 0;
      z-index: 10;
      backdrop-filter: blur(14px);
    }

    .nav {
      display: grid;
      grid-template-columns: 1fr auto 1fr;
      align-items: center;
      gap: 28px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 13px;
      font-weight: 800;
      font-size: 25px;
      letter-spacing: 0;
      white-space: nowrap;
    }

    .mark {
      width: 36px;
      height: 36px;
      position: relative;
      border: 3px solid #111;
      clip-path: polygon(0 0, 28% 0, 50% 22%, 72% 0, 100% 0, 100% 100%, 78% 100%, 78% 34%, 50% 64%, 22% 34%, 22% 100%, 0 100%);
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 42px;
      color: #74777c;
      font-size: 18px;
      white-space: nowrap;
    }

    .nav-links a,
    .account a {
      color: inherit;
      text-decoration: none;
    }

    .account {
      justify-self: end;
      display: flex;
      align-items: center;
      gap: 30px;
      color: #777b82;
      font-weight: 650;
      font-size: 18px;
      white-space: nowrap;
    }

    .lang {
      width: 26px;
      height: 26px;
      display: inline-grid;
      place-items: center;
      color: #676b72;
    }

    .credit { color: #686b72; }
    .avatar {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 1px solid var(--line);
      display: inline-grid;
      place-items: center;
      background: #fafafa;
      color: #777b82;
      font-weight: 500;
    }

    .hero {
      min-height: 290px;
      display: grid;
      place-items: center;
      text-align: center;
      border-bottom: 1px solid var(--line);
      background:
        repeating-linear-gradient(135deg, rgba(12, 18, 28, .035) 0 1px, transparent 1px 13px),
        #fff;
    }

    .hero h1 {
      margin: 12px 0 16px;
      font-size: clamp(34px, 3.1vw, 60px);
      line-height: 1.1;
      font-weight: 820;
      letter-spacing: 0;
    }

    .hero p {
      margin: 0;
      color: #7f838a;
      font-size: clamp(17px, 1.25vw, 24px);
      font-weight: 500;
    }

    .market {
      padding: 70px 0 90px;
      display: grid;
      grid-template-columns: 285px minmax(0, 1fr);
      column-gap: 56px;
      row-gap: 36px;
      align-items: start;
    }

    .toolbar {
      grid-column: 1 / -1;
      display: grid;
      grid-template-columns: 285px minmax(0, 1fr);
      gap: 56px;
      align-items: center;
    }

    .tabs {
      width: max-content;
      display: inline-flex;
      gap: 6px;
      padding: 6px;
      border-radius: 14px;
      background: #f2f2f3;
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, .9);
    }

    .tab {
      min-width: 88px;
      height: 50px;
      border: 0;
      border-radius: 10px;
      background: transparent;
      color: #777b81;
      font-weight: 720;
      font-size: 18px;
      cursor: pointer;
    }

    .tab.active {
      color: #18191b;
      background: #fff;
      box-shadow: 0 8px 20px rgba(14, 18, 28, .08);
    }

    .tools {
      justify-self: end;
      display: grid;
      grid-template-columns: minmax(260px, 380px) 285px;
      gap: 12px;
      width: min(665px, 100%);
    }

    .search,
    .select {
      height: 68px;
      border: 1px solid #dedfe2;
      border-radius: 14px;
      background: #fff;
      display: flex;
      align-items: center;
      color: #7a7d84;
      box-shadow: 0 2px 8px rgba(18, 23, 34, .03);
    }

    .search {
      gap: 14px;
      padding: 0 18px;
    }

    .search svg {
      width: 24px;
      height: 24px;
      flex: 0 0 auto;
    }

    .search input {
      width: 100%;
      min-width: 0;
      border: 0;
      outline: 0;
      color: #222;
      font-size: 17px;
      background: transparent;

