        radial-gradient(circle at 37% 32%, #ffd6df 0 45px, transparent 47px),
        radial-gradient(circle at 61% 32%, #ffd6df 0 45px, transparent 47px),
        radial-gradient(circle at 50% 55%, #f55f80 0 38px, transparent 39px),
        linear-gradient(135deg, #ffe6ed, #fff4ce 50%, #e7fff0);
    }

    .img-shelf {
      background-image: url("https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=900&q=80");
    }

    .img-city {
      background-image: url("https://images.unsplash.com/photo-1518005020951-eccb494ad742?auto=format&fit=crop&w=900&q=80");
    }

