    }

    @media (max-width: 820px) {
      .site-header { height: auto; padding: 18px 0; position: static; }
      .nav {
        grid-template-columns: 1fr auto;
        row-gap: 16px;
      }
      .nav-links {
        grid-column: 1 / -1;
        grid-row: 2;
        justify-content: flex-start;
        overflow-x: auto;
        padding-bottom: 4px;
      }
      .account { gap: 14px; }
      .credit { display: none; }
      .hero { min-height: 230px; padding: 48px 0; }
      .market,
      .toolbar {
        grid-template-columns: 1fr;
      }
      .market { padding: 40px 0 70px; }
      .tools {
        justify-self: stretch;
        grid-template-columns: 1fr;
        width: 100%;
      }
      .filters {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 22px;
        padding-top: 0;
      }
      .filter-group + .filter-group { margin-top: 0; }
      .grid { grid-template-columns: 1fr; }
    }

    @media (max-width: 560px) {
      .container { width: min(100% - 28px, 520px); }
      .brand { font-size: 21px; }
      .mark { width: 30px; height: 30px; }
