      .lang { display: none; }
      .avatar { width: 38px; height: 38px; }
      .tabs { width: 100%; }
      .tab { flex: 1; min-width: 0; }
      .filters { grid-template-columns: 1fr; }
      .visual { height: 230px; }
      .card-body { padding: 19px 20px; }
      .chat { right: 18px; bottom: 18px; }
    }
